const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define lake locations (Tibet region)
  // Dorsoidong Co: approximately 31.95°N, 89.65°E
  const dorsoidong = ee.Geometry.Point([89.65, 31.95]);

  // Chibzhang Co: approximately 31.45°N, 90.15°E
  const chibzhang = ee.Geometry.Point([90.15, 31.45]);

  // Create buffer zones for sampling
  const dorsoidongRegion = dorsoidong.buffer(1000);
  const chibzhangRegion = chibzhang.buffer(1000);

  // Target date with some flexibility
  const targetDate = '1987-10-12';
  const startDate = '1987-10-01';
  const endDate = '1987-10-31';

  // Landsat 5 collection for 1987
  let collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(dorsoidong.buffer(50000));

  const collectionSize = collection.size().getInfo();
  console.log('Total images found:', collectionSize);

  if (collectionSize === 0) {
    console.log('No images found for October 1987.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the closest image to target date
  const image = collection.sort('system:time_start').first();
  const imageDate = new Date(image.get('system:time_start').getInfo());
  console.log('Using image from:', imageDate.toISOString().split('T')[0]);

  // Apply scaling factors for Landsat Collection 2
  function applyScaling(img) {
    const optical = img.select('SR_B.*').multiply(0.0000275).add(-0.2);
    return img.addBands(optical, null, true);
  }

  const scaledImage = applyScaling(image);

  // Use blue band (SR_B1 for Landsat 5)
  const blueImage = scaledImage.select('SR_B1');

  // Calculate mean blue reflectance for Dorsoidong Co
  const dorsoidongStats = blueImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: dorsoidongRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const dorsoidongBlue = dorsoidongStats.get('SR_B1_mean').getInfo();
  const dorsoidongCount = dorsoidongStats.get('SR_B1_count').getInfo();

  console.log('Dorsoidong Co - Blue:', dorsoidongBlue, 'Pixels:', dorsoidongCount);

  // Calculate mean blue reflectance for Chibzhang Co
  const chibzhangStats = blueImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: chibzhangRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const chibzhangBlue = chibzhangStats.get('SR_B1_mean').getInfo();
  const chibzhangCount = chibzhangStats.get('SR_B1_count').getInfo();

  console.log('Chibzhang Co - Blue:', chibzhangBlue, 'Pixels:', chibzhangCount);

  // Validation
  if (dorsoidongCount === 0 || chibzhangCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (dorsoidongBlue === null || chibzhangBlue === null || 
      isNaN(dorsoidongBlue) || isNaN(chibzhangBlue) ||
      dorsoidongBlue < 0 || dorsoidongBlue > 1 ||
      chibzhangBlue < 0 || chibzhangBlue > 1) {
    console.log('Invalid reflectance values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: lighter blue = higher blue reflectance
  if (dorsoidongBlue > chibzhangBlue) {
    console.log('Dorsoidong Co has lighter blue color.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Chibzhang Co has equal or lighter blue color.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
